/**
 * Chart-stability golden: the TS port of chartStability must report the same
 * facts, in the same order, with the same values and the same change
 * instants as the Python reference. Both run the SAME specs (from
 * stability-golden.json, generated by python/export_stability_golden.py).
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { loadNodeData } from "../src/node-loader.js";
import { chartStability } from "../src/stability.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/stability-golden.json"), "utf8"));
const eng = new Engine(loadNodeData(join(here, "../../data"), "embedded", "full"));

let checks = 0;
let failures = 0;
let worst = 0;
const TOL = 2e-5; // days (~1.7 s): changes are bisected to about a second

const ok = (cond: boolean, msg: string): void => {
  checks++;
  if (!cond) { failures++; console.error(`FAIL ${msg}`); }
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.cases as any[]) {
  const o = c.options ?? {};
  const got = chartStability(eng, c.jd, {
    lat: c.lat ?? undefined, lonEast: c.lon ?? undefined,
    halfWidthSeconds: o.half_width_seconds, houseSystem: o.house_system,
    zodiac: o.zodiac, stepSeconds: o.step_seconds,
  });
  const want = c.result;
  ok(Math.abs(got.halfWidthSeconds - want.half_width_seconds) < 1e-9, `${c.id}: half-width`);
  ok(got.from === want.from && got.to === want.to, `${c.id}: window`);
  ok(got.summary.facts === want.summary.facts && got.summary.stable === want.summary.stable,
    `${c.id}: summary ${JSON.stringify(got.summary)} vs ${JSON.stringify(want.summary)}`);
  ok(got.facts.length === want.facts.length, `${c.id}: ${got.facts.length} facts vs ${want.facts.length}`);
  for (let i = 0; i < Math.min(got.facts.length, want.facts.length); i++) {
    const g = got.facts[i];
    const w = want.facts[i];
    const tag = `${c.id} ${w.kind} ${w.subject}`;
    ok(g.kind === w.kind && g.subject === w.subject, `${tag}: order (got ${g.kind} ${g.subject})`);
    ok(g.value === w.value, `${tag}: value ${g.value} vs ${w.value}`);
    ok(g.stable === w.stable, `${tag}: stable`);
    ok(Math.abs(g.share - w.share) < 1e-4, `${tag}: share ${g.share} vs ${w.share}`);
    ok(g.segments.length === w.segments.length, `${tag}: ${g.segments.length} segments vs ${w.segments.length}`);
    for (let j = 0; j < Math.min(g.segments.length, w.segments.length); j++) {
      ok(g.segments[j].value === w.segments[j].value, `${tag} segment ${j}: value`);
      for (const k of ["from", "to"] as const) {
        const diff = Math.abs(g.segments[j][k] - w.segments[j][k]);
        if (diff > worst) worst = diff;
        ok(diff <= TOL, `${tag} segment ${j}.${k}: diff ${diff} d`);
      }
    }
  }
}

for (const [o, why] of [
  [{ lat: 10 }, "lat without lonEast"],
  [{ halfWidthSeconds: -1 }, "negative half-width"],
  [{ halfWidthSeconds: 60, stepSeconds: 0 }, "zero step"],
] as const) {
  let threw = false;
  try { chartStability(eng, 2451545.0, o); } catch (e) { threw = e instanceof RangeError; }
  ok(threw, `should reject: ${why}`);
}

console.log(`${checks} checks, ${failures} failures`);
console.log(`worst edge diff: ${worst.toExponential(2)} d`);
process.exit(failures === 0 ? 0 : 1);
